                    if (GetGossipPhrase(phrase)) {
                        if (test)
                            return true;
                        if (AIAction_SpeakToTarget(AI_ACTION_REPEAT_ONCE, &GetCreature(), p_player, phrase, false, 0x93, false)
                                == AI_ACTION_RETURN_SUCCESS)
                            spoke = true;
